import hashlib

SECRET = "P.8CGq@Wr~Vs]!4!"

def calc_key(params_list):
    # 字典序排序
    arr = sorted(params_list)
    # 拼接: &p1=v1&p2=v2...
    sorted_str = "&" + "&".join(arr)
    return hashlib.md5((SECRET + sorted_str).encode()).hexdigest()

def calc_key_from_map(param_map):
    # 排除 $*$ 前缀参数
    params = [f"{k}={v}" for k, v in param_map.items() if not k.startswith("$*$")]
    return calc_key(params)

import hashlib, base64, json, requests, urllib3 from Crypto.Cipher import AES urllib3.disable_warnings()
AES_KEY = b"P.8CGq@Wr~Vs]!4!" LOGIN_BASE = "http://rtkapi.ruansky.net/" API_BASE = "https://rtkapi2.ruansky.net/"
def md5(s): return hashlib.md5(s.encode()).hexdigest()
def unicode_escape(s): return "".join("\\u00"+format(ord(c),'x') if ord(c)<=256 else "\\u"+format(ord(c),'x') for c in s)
def decrypt(resp_json): data = base64.b64decode(resp_json["data"]) iv = base64.b64decode(resp_json["iv"]) cipher = AES.new(AES_KEY, AES.MODE_CBC, iv) text = cipher.decrypt(data).rstrip(b'\x00').decode('utf-8','ignore').strip() return json.loads(text)
def calc_key(params_list): arr = sorted(params_list) return md5(AES_KEY.decode() + "&" + "&".join(arr))
