url = (f"{LOGIN_BASE}member/loginVerify?channel=yingyongbao" f"&version=8730&api_level=33&phone_model={phone_model}" f"&os_info=V1__unknown&uname={uname}&upsw={upsw}" f"&device_id=a1b2c3d4e5f6g7h8" f"&device_name=samsung_SM-G9910&client_id=1&key={key}")
resp = requests.get(url, verify=False, headers={"User-Agent": "okhttp/4.9.3"}) login = decrypt(resp.json()) uid = str(login["data"]["uid"]) token = login["data"]["token"] print(f"登录成功: UID={uid}")
